test_code:
assert abs(safe_sqrt(16) - 4.0) < 1e-9
try:
    safe_sqrt(-1)
    assert False, 'expected NegativeNumberError'
except NegativeNumberError:
    pass

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}
order = topological_sort(graph)
assert set(order) == {'A', 'B', 'C', 'D'}
pos = {node: i for i, node in enumerate(order)}
assert pos['A'] < pos['B']
assert pos['A'] < pos['C']
assert pos['B'] < pos['D']
assert pos['C'] < pos['D']
